WITH RECURSIVE x6 AS (SELECT ST_CONTAINS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(POLYGON((5 0,0 10,10 10,5 0)), POLYGON((5 0,0 -10,10 -10,5 0)))'), ST_GEOMFROMTEXT('LINESTRING(5 -2,5 2)')) AS x8 FROM x9 GROUP BY x1.v115586 + 0, x1.v115586 + 0) SELECT x1.v115586 + 900000, (NOT (NOT x1.v115586 IN (x1.v115586, x1.v115586))) + 0.7, NULLIF(x1.v115586, x1.v115586) AS x0, 27 + 9000 FROM v115585 AS x1 WHERE x1.v115586 + 4 > 5